// Prints a JSON report on stdout: per-step {name, file, text, defects:[...]}
// where defects are the literal strings [object Object], [object ...], undefined,
// NaN, plus every console error and page error.

import { chromium } from "playwright";
import { writeFileSync, mkdirSync } from "node:fs";

const arg = (k, d) => {
  const i = process.argv.indexOf("--" + k);
  return i === -1 ? d : process.argv[i + 1];
};
const url = arg("url");
const out = arg("out");
const label = arg("label", "run");
const headful = !process.argv.includes("--headless");
const W = Number(arg("width", 390));
const H = Number(arg("height", 844));

mkdirSync(out, { recursive: true });

const BAD = [
  /\[object [A-Za-z]+\]/g,
  /(^|[^\\w])undefined([^\\w]|$)/g,
  /(^|[^\\w])NaN([^\\w]|$)/g,
  /\\[object [^\\]]*\\]/g,
];

const report = { url, label, viewport: { width: W, height: H }, steps: [], consoleErrors: [], pageErrors: [] };

const browser = await chromium.launch({
  headless: !headful,
  args: ["--no-sandbox", "--disable-dev-shm-usage", "--ozone-platform-hint=auto"],
});
const ctx = await browser.newContext({
  viewport: { width: W, height: H },
  deviceScaleFactor: 2,
  isMobile: true,
  hasTouch: true,
  userAgent:
    "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1",
});
const page = await ctx.newPage();
page.on("console", (m) => {
  if (m.type() === "error" || m.type() === "warning")
    report.consoleErrors.push({ step: currentStep, type: m.type(), text: m.text() });
});
page.on("pageerror", (e) => report.pageErrors.push({ step: currentStep, text: String(e) }));

let currentStep = "load";
