  currentStep = name;
  await page.waitForTimeout(ms);
  const file = `${out}/${label}-${name}.png`;
  await page.screenshot({ path: file, fullPage: false });
  const text = await page.evaluate(() => document.body.innerText);
  const defects = [];
  for (const re of BAD) {
