cap = r'''
// quick capture: record ws events for a session, print the distinct data.type inventory
const base = process.argv[2];
const want = process.argv[3];
const secs = await (await fetch(base + "/api/sessions")).json();
const list = secs.data;
console.error("sessions:", list.length);
const t = await (await fetch(base + "/api/ws-ticket", {method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({scope:"browser"})})).json();
const ws = new WebSocket(base.replace("http","ws") + "/ws?ticket=" + encodeURIComponent(t.data.ticket));
const out = [];
const inv = new Map();
ws.onopen = () => ws.send(JSON.stringify({type:"subscribe", sessionId: want, lastSeq: 0}));
ws.onmessage = (m) => {
  const o = JSON.parse(m.data);
  out.push(o);
  const evs = o.events || (o.event ? [o.event] : []);
  for (const e of evs) {
    const d = e.event ? e.event.data : e.data;
    const ty = d && d.type;
    const k = e.eventType + " | " + ty;
    if (!inv.has(k)) inv.set(k, {count:0, keys:new Set(), sample:null});
    const r = inv.get(k); r.count++;
    for (const kk of Object.keys(d||{})) r.keys.add(kk);
    if (!r.sample) r.sample = d;
  }
};
setTimeout(() => {
  console.error("messages:", out.length);
  for (const [k,v] of inv) console.error(k, "x"+v.count, "keys:", [...v.keys].join(","));
  console.log(JSON.stringify(out));
  process.exit(0);
}, 20000);
'''
