newsweep2 = r'''
// Run the NEW describeEvent() over the recorded real stream and assert that no
// rendered LINE carries a value that fell through as "[object …]", a bare
// `undefined`, or `NaN`.
//
// The check is deliberately narrow. `[object …]` is banned anywhere: no real
// payload ever contains it. `undefined` / `NaN` are banned only in VALUE
// POSITION — a line that is exactly that word, or a `key: value` pair whose
// value is it. The bare word legitimately occurs inside source code an agent
// printed ("... | number | boolean | undefined {"), and flagging that would be
// the check lying rather than the renderer failing.
import { readFileSync, readdirSync } from "node:fs";
import { describeEvent } from "/projects/dash-mobile-render-20260930/fork/public/mobile/src/format.js";
const DIR = "/projects/dash-mobile-render-20260930/artifacts/fixtures";
const OBJECT = /\[object [^\]]*\]/;
const BARE = /^\s*(-|\*)?\s*(undefined|NaN|null)\s*:?\s*$/;
const VALUE = /:\s*(undefined|NaN)\s*$/;
const isBad = (t) => OBJECT.test(t) || BARE.test(t) || VALUE.test(t);

let total = 0, bad = 0;
const byType = new Map();
const offenders = [];
for (const f of readdirSync(DIR).filter((f) => f.endsWith(".jsonl"))) {
  for (const line of readFileSync(DIR + "/" + f, "utf8").split("\n")) {
    if (!line.trim()) continue;
    for (const { event } of JSON.parse(line).events || []) {
      total++;
      const d = describeEvent(event);
      byType.set(event.eventType, (byType.get(event.eventType) || 0) + 1);
      const texts = [d.title, ...d.lines.map((l) => String(l.text))];
      const hit = texts.filter(isBad);
      if (hit.length) {
        bad++;
        if (offenders.length < 5) offenders.push({ file: f, type: event.eventType, hit: hit.slice(0, 2).map((t) => t.slice(0, 160)) });
      }
    }
  }
}
console.log(JSON.stringify({ totalEvents: total, badEvents: bad, distinctEventTypes: byType.size, offenders }, null, 2));
process.exit(bad === 0 ? 0 : 1);
'''
open("/projects/dash-mobile-render-20260930/tools/render/new-sweep.mjs","w").write(newsweep2)
