newsweep3 = r'''
// Sweep the NEW describeEvent() over every recorded real event and prove no
// STRUCTURAL part of the rendering carries a value that fell through.
//
// WHERE the ban applies, and why not everywhere:
//   * the title line (`.who` in the DOM)          — always renderer-authored
//   * meta / err lines                            — renderer-authored summaries
//   * ANY line that IS the bad token by itself    — nothing legitimate is
// A text/thinking/tool line is VERBATIM payload: this very stream contains an
// agent's own sentence "→ \"[object Object]\"", and policing content would make
// the check lie. See NOTES.md, "the check that had to be narrowed".
import { readFileSync, readdirSync } from "node:fs";
import { describeEvent } from "/projects/dash-mobile-render-20260930/fork/public/mobile/src/format.js";

const DIR = "/projects/dash-mobile-render-20260930/artifacts/fixtures";
const OBJECT = /\[object [^\]]*\]/;
const BARE = /^\s*(undefined|NaN)$/;
const VALUE = /:\s*(undefined|NaN)\s*$/;
const STRUCTURAL = new Set(["meta", "err"]);

let total = 0, bad = 0, empty = 0;
const byType = new Map();
const offenders = [];
for (const f of readdirSync(DIR).filter((f) => f.endsWith(".jsonl"))) {
  for (const line of readFileSync(DIR + "/" + f, "utf8").split("\n")) {
    if (!line.trim()) continue;
    for (const { event } of JSON.parse(line).events || []) {
      total++;
      const d = describeEvent(event);
      byType.set(event.eventType, (byType.get(event.eventType) || 0) + 1);
      if (d.lines.length === 0) empty++;
      const checked = [d.title, ...d.lines.map((l) => ({ t: String(l.text), structural: STRUCTURAL.has(l.cls) }))];
      const hit = checked.filter((c) => BARE.test(c.t) || (c.structural && (OBJECT.test(c.t) || VALUE.test(c.t))));
      if (hit.length) {
        bad++;
        if (offenders.length < 5) offenders.push({ file: f, type: event.eventType, hit: hit.slice(0, 2).map((c) => c.t.slice(0, 160)) });
      }
    }
  }
}
console.log(JSON.stringify({ totalEvents: total, badEvents: bad, eventsWithNoLines: empty, distinctEventTypes: byType.size, offenders }, null, 2));
process.exit(bad === 0 ? 0 : 1);
'''
