// Sweep the NEW describeEvent() over every recorded real event and prove the
// renderer never INVENTS a "[object …]", a bare `undefined`, or a `NaN`.
//
// The subtlety that made the first two versions of this check wrong: the
// stream contains arbitrary agent text, and this very session's transcript is
// in the fixture, complete with the sentence "→ \"[object Object]\"". A check
// that greps the rendered text therefore flags the DATA, not the defect, and a
// check that greps only structural lines misses a value the renderer built.
//
// So the test is provenance-based, not pattern-based: a bad token in the
// rendering is a DEFECT only when that token does not occur anywhere in the
// raw event JSON it was rendered from. If the source said it, we printed it;
// if the source did not, we made it up. That is falsifiable in both directions.
import { readFileSync, readdirSync } from "node:fs";
import { describeEvent } from "/projects/dash-mobile-render-20260930/fork/public/mobile/src/format.js";

const DIR = "/projects/dash-mobile-render-20260930/artifacts/fixtures";
const TOKENS = [/\[object [^\]]*\]/g, /(^|[\s:,(])(undefined|NaN)(?=[\s,).:]|$)/g];

let total = 0, invented = 0, echoed = 0;
const byType = new Map();
const offenders = [];
for (const f of readdirSync(DIR).filter((f) => f.endsWith(".jsonl"))) {
  for (const line of readFileSync(DIR + "/" + f, "utf8").split("\n")) {
    if (!line.trim()) continue;
    for (const { event } of JSON.parse(line).events || []) {
      total++;
      const d = describeEvent(event);
      byType.set(event.eventType, (byType.get(event.eventType) || 0) + 1);
      const rendered = [d.title, ...d.lines.map((l) => String(l.text))].join("\n");
      const source = JSON.stringify(event);
      let isInvented = false, isEchoed = false;
      for (const re of TOKENS) {
        for (const m of rendered.matchAll(re)) {
          const tok = m[0].trim();
          if (source.includes(tok)) isEchoed = true;
          else {
            isInvented = true;
            if (offenders.length < 6) offenders.push({ file: f, type: event.eventType, token: tok, line: rendered.slice(0, 200) });
          }
        }
      }
      if (isInvented) invented++;
      if (isEchoed) echoed++;
    }
  }
}
console.log(JSON.stringify({ totalEvents: total, rendererInventedBadTokens: invented, badTokensEchoedFromPayload: echoed, distinctEventTypes: byType.size, offenders }, null, 2));
process.exit(invented === 0 ? 0 : 1);
